from solution import house_bowling

def test_zeros():
    assert house_bowling([0]*20) == 0

def test_single_strike():
    assert house_bowling([10] + [0]*18) == 10

def test_all_strikes():
    # 10 frames of strikes, 10 rolls
    # frames 1-8: 30 each = 240; frame 9: 10+10=20; frame 10: 10
    assert house_bowling([10]*10) == 270

def test_frame9_strike_frame10_strike():
    rolls = [0]*16 + [10, 10]
    assert house_bowling(rolls) == 30

def test_frame9_strike_frame10_open():
    rolls = [0]*16 + [10, 3, 4]
    assert house_bowling(rolls) == 10 + 3 + 4 + 3 + 4

def test_frame10_spare_no_bonus():
    rolls = [0]*18 + [5, 5]
    assert house_bowling(rolls) == 10

def test_frame9_spare_frame10_strike():
    rolls = [0]*16 + [5, 5, 10]
    assert house_bowling(rolls) == 20 + 10

def test_all_spares():
    rolls = [5]*20
    # frames 1-9: 15 each = 135; frame 10: 10
    assert house_bowling(rolls) == 145

def test_all_ones():
    assert house_bowling([1]*20) == 20

def test_strike_then_spare():
    rolls = [10, 4, 6] + [0]*14 + [0, 0]
    # strike: 10+4+6=20; spare: 10+0=10
    assert house_bowling(rolls) == 30

def test_frame10_zero_ten_spare():
    rolls = [0]*18 + [0, 10]
    assert house_bowling(rolls) == 10

def test_two_strikes_then_open():
    rolls = [10, 10, 3, 4] + [0]*14
    # 23 + 17 + 7
    assert house_bowling(rolls) == 47
